'use client';

import { Button } from '@fusai/ui/components/button';
import { Download, Loader2 } from 'lucide-react';
import { useState } from 'react';
import { toast } from 'sonner';
import { API_URL } from '@/lib/config';

/** Downloads FUSAI.md, generated by the API with the project's current settings. */
export function DownloadFusaiMd({ projectId }: { projectId: string }) {
  const [pending, setPending] = useState(false);

  async function download() {
    setPending(true);
    try {
      const res = await fetch(`${API_URL}/internal/projects/${projectId}/fusai-md`, {
        credentials: 'include',
      });
      if (!res.ok) throw new Error(String(res.status));
      const url = URL.createObjectURL(await res.blob());
      const a = document.createElement('a');
      a.href = url;
      a.download = 'FUSAI.md';
      a.click();
      URL.revokeObjectURL(url);
    } catch {
      toast.error('Não foi possível gerar o FUSAI.md.');
    } finally {
      setPending(false);
    }
  }

  return (
    <Button variant="brand" onClick={download} disabled={pending} className="w-fit">
      {pending ? <Loader2 className="animate-spin" /> : <Download />}
      Baixar FUSAI.md
    </Button>
  );
}
